const body = $json.body ?? $json;
const question = body.question;

let isValid = true;
let validationError = null;

if (question === undefined || question === null) {
  isValid = false;
  validationError = 'The question field is required.';
} else if (typeof question !== 'string') {
  isValid = false;
  validationError = 'The question must be a string.';
} else if (question.trim().length === 0) {
  isValid = false;
  validationError = 'The question cannot be empty.';
} else if (question.trim().length > 500) {
  isValid = false;
  validationError = 'The question must not exceed 500 characters.';
}

return {
  json: {
    question: typeof question === 'string' ? question.trim() : question,
    is_valid: isValid,
    validation_error: validationError
  }
};

const rows = $input.all().map(item => item.json);
const validator = $('Validate Generated SQL').first().json;

return [
  {
    json: {
      question: validator.question,
      query_uuid: validator.query_uuid,
      generated_sql: validator.sql,
      sql_intent: validator.intent,
      sql_reason: validator.reason,
      is_safe: true,
      result_row_count: rows.length,
      database_result: rows
    }
  }
];

