function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const queryUuid = generateUUID();

return {
  json: {
    ...$json,
    query_uuid: queryUuid
  }
};

const input = $json;

// ----------------------------------------------------
// PRESERVE ORIGINAL REQUEST DATA
// ----------------------------------------------------

const question =
  $('Generate Query UUID').first().json.question ?? '';

const queryUuid =
  $('Generate Query UUID').first().json.query_uuid ?? null;

// Support different Structured Output Parser shapes
const rawSql =
  input.sql ??
  input.output?.sql ??
  input.response?.sql ??
  '';

const intent =
  input.intent ??
  input.output?.intent ??
  input.response?.intent ??
  '';

const reason =
  input.reason ??
  input.output?.reason ??
  input.response?.reason ??
  '';

const allowed =
  input.allowed ??
  input.output?.allowed ??
  input.response?.allowed ??
  true;

let sql = typeof rawSql === 'string' ? rawSql.trim() : '';

let isSafe = true;
let safetyError = null;

// ----------------------------------------------------
// SECURITY LAYER 1:
// CHECK ORIGINAL USER INTENT
// ----------------------------------------------------

const destructiveIntentPatterns = [
  /\bdelete\b/i,
  /\bdrop\b/i,
  /\btruncate\b/i,
  /\binsert\b/i,
  /\bupdate\b/i,
  /\balter\b/i,
  /\bcreate\s+(table|schema|database|view|index)\b/i,
  /\breplace\b/i,
  /\boverwrite\b/i,
  /\bupsert\b/i,
  /\bgrant\b/i,
  /\brevoke\b/i,
  /\bremove\s+(all|the|these|those|lead|leads|record|records|row|rows)\b/i,
  /\berase\b/i,
  /\bdestroy\b/i,
  /\bmodify\s+(the\s+)?(database|table|record|records|lead|leads)\b/i,
  /\bchange\s+(the\s+)?(database|table|record|records)\b/i
];

for (const pattern of destructiveIntentPatterns) {
  if (pattern.test(question)) {
    isSafe = false;
    safetyError =
      'Destructive or write database requests are not allowed. Only read-only analytical questions can be executed.';
    break;
  }
}

// ----------------------------------------------------
// SECURITY LAYER 2:
// CHECK AI ALLOWED FLAG
// ----------------------------------------------------

if (isSafe && allowed === false) {
  isSafe = false;
  safetyError =
    'The request was classified as non-read-only and cannot be executed.';
}

// ----------------------------------------------------
// SECURITY LAYER 3:
// SQL MUST EXIST
// ----------------------------------------------------

if (isSafe && !sql) {
  isSafe = false;
  safetyError = 'No SQL query was generated.';
}

// ----------------------------------------------------
// SECURITY LAYER 4:
// BLOCK SQL COMMENTS
// ----------------------------------------------------

if (isSafe && /--|\/\*|\*\//i.test(sql)) {
  isSafe = false;
  safetyError = 'SQL comments are not allowed.';
}

// ----------------------------------------------------
// REMOVE ONE OPTIONAL TRAILING SEMICOLON
// ----------------------------------------------------

if (sql.endsWith(';')) {
  sql = sql.slice(0, -1).trim();
}

// ----------------------------------------------------
// SECURITY LAYER 5:
// BLOCK MULTIPLE STATEMENTS
// ----------------------------------------------------

if (isSafe && sql.includes(';')) {
  isSafe = false;
  safetyError = 'Multiple SQL statements are not allowed.';
}

// ----------------------------------------------------
// SECURITY LAYER 6:
// SELECT ONLY
// ----------------------------------------------------

if (isSafe && !/^SELECT\b/i.test(sql)) {
  isSafe = false;
  safetyError = 'Only SELECT queries are allowed.';
}

// ----------------------------------------------------
// SECURITY LAYER 7:
// BLOCK FORBIDDEN SQL KEYWORDS
// ----------------------------------------------------

const forbiddenKeywords = [
  'INSERT',
  'UPDATE',
  'DELETE',
  'DROP',
  'TRUNCATE',
  'ALTER',
  'CREATE',
  'GRANT',
  'REVOKE',
  'MERGE',
  'REPLACE',
  'UPSERT',
  'COPY',
  'CALL',
  'EXECUTE',
  'DO',
  'VACUUM',
  'ANALYZE',
  'COMMENT'
];

if (isSafe) {
  for (const keyword of forbiddenKeywords) {
    const regex = new RegExp(`\\b${keyword}\\b`, 'i');

    if (regex.test(sql)) {
      isSafe = false;
      safetyError =
        `Forbidden SQL keyword detected: ${keyword}`;
      break;
    }
  }
}

// ----------------------------------------------------
// SECURITY LAYER 8:
// ONLY ALLOW LEADS TABLE
// ----------------------------------------------------

if (
  isSafe &&
  !/\bFROM\s+(public\.)?leads\b/i.test(sql)
) {
  isSafe = false;
  safetyError =
    'Queries may only read from the public.leads table.';
}

// ----------------------------------------------------
// OUTPUT
// ----------------------------------------------------

return {
  json: {
    question,
    query_uuid: queryUuid,
    allowed,
    sql,
    intent,
    reason,
    is_safe: isSafe,
    safety_error: safetyError
  }
};
